//! Tests: pion/rtp v1.10.6, pion/rtcp v1.2.20 and pion/interceptor v0.1.51 (TWCC recorder)
//! byte vectors, round trips, streams, TWCC and the bandwidth estimator on simulated links.

use std::time::{Duration, Instant};

use crate::*;

pub(crate) fn hex(s: &str) -> Vec<u8> {
    let s: String = s.chars().filter(char::is_ascii_hexdigit).collect();
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

