/// Seeds for the `rtp_rtcp` fuzz corpus.
pub(crate) fn seeds() -> Vec<Vec<u8>> {
    let mut v: Vec<Vec<u8>> = [
        PION_RTP_ONE_BYTE,
        PION_RTP_TWO_BYTE,
        PION_SR,
        PION_RR,
        PION_NACK,
        PION_PLI,
        PION_FIR,
        PION_REMB,
        PION_SDES,
        PION_BYE,
        PION_TWCC_1,
        PION_TWCC_2,
    ]
    .iter()
    .map(|s| hex(s))
    .collect();
    let all: Vec<Rtcp> = rtcp_samples();
    v.push(write_compound(&all));
    // RFC 6679: a report with an ECN feedback message and an XR ECN summary.
    let counters = EcnCounters {
        ect0: 1,
        ect1: 900,
        ce: 12,
        not_ect: 40,
        lost: 3,
        duplicates: 1,
    };
    v.push(write_compound(&[
        Rtcp::ReceiverReport {
            ssrc: 4,
            reports: vec![block(2)],
        },
        EcnFeedback {
            sender_ssrc: 4,
            media_ssrc: 2,
            extended_highest_seq: 0x0002_0010,
            counters,
        }
        .to_rtcp(),
        Rtcp::ExtendedReport {
            ssrc: 4,
            blocks: vec![EcnSummary::to_xr(&[EcnSummary { ssrc: 2, counters }])],
        },
    ]));
    v
}

fn block(ssrc: u32) -> ReportBlock {
    ReportBlock {
        ssrc,
        fraction_lost: 3,
        cumulative_lost: -5,
        extended_highest_seq: 0x0002_0010,
        jitter: 77,
        last_sr: 0x1234_5678,
        delay_since_last_sr: 65536,
    }
}

