// --- RTP header ---

fn audio_map() -> ExtensionMap {
    ExtensionMap::default_audio()
}

fn video_map() -> ExtensionMap {
    ExtensionMap::default_video()
}

#[test]
fn extension_uris_and_maps() {
    for e in Extension::ALL {
        assert_eq!(Extension::from_uri(e.uri()), Some(e));
    }
    assert_eq!(Extension::from_uri("urn:nope"), None);
    let mut m = ExtensionMap::new();
    assert!(m.is_empty());
    m.insert(3, Extension::Mid);
    m.insert(5, Extension::Mid); // moves Mid
    m.insert(5, Extension::AudioLevel); // replaces id 5
    m.insert(0, Extension::TransportCc); // ignored
    assert_eq!(m.get(5), Some(Extension::AudioLevel));
    assert_eq!(m.id_of(Extension::Mid), None);
    assert_eq!(m.id_of(Extension::TransportCc), None);
    m.insert(200, Extension::Mid);
    assert_eq!(
        m.iter().collect::<Vec<_>>(),
        [(5, Extension::AudioLevel), (200, Extension::Mid)]
    );
    m.remove(Extension::Mid);
    assert_eq!(m.get(200), None);
    assert_eq!(audio_map().id_of(Extension::AudioLevel), Some(1));
    assert_eq!(video_map().id_of(Extension::RtpStreamId), Some(10));
    assert_eq!(video_map().id_of(Extension::AudioLevel), None);
}

#[test]
fn pion_rtp_one_byte() {
    let p = hex(PION_RTP_ONE_BYTE);
    let h = RtpHeader::parse(&p, &audio_map()).unwrap();
    assert!(h.marker);
    assert_eq!(
        (h.payload_type, h.sequence_number, h.timestamp, h.ssrc),
        (111, 0x1234, 0xdead_beef, 0x1122_3344)
    );
    assert_eq!(h.csrc, [1, 2]);
    assert_eq!(h.ext.audio_level, Some((true, 0x0a)));
    assert_eq!(h.ext.abs_send_time, Some(0x01_0203));
    assert_eq!(h.ext.transport_cc, Some(0x0102));
    assert_eq!(h.ext.mid.as_deref(), Some("audio0"));
    assert_eq!(h.payload(&p), b"opus");
    assert_eq!(h.padding_len, 0);
    assert_eq!(h.write(&audio_map(), b"opus"), p);
}

#[test]
fn pion_rtp_two_byte_padding() {
    let p = hex(PION_RTP_TWO_BYTE);
    let map = video_map();
    let h = RtpHeader::parse(&p, &map).unwrap();
    assert_eq!(h.sequence_number, 65535);
    assert_eq!(h.ext.mid.as_deref(), Some("0"));
    assert_eq!(h.ext.rid.as_deref(), Some("hi"));
    assert_eq!(h.ext.rrid.as_deref(), Some("abcdefghijklmnopqrst"));
    assert_eq!(h.ext.video_orientation, Some(3));
    assert_eq!(h.padding_len, 4);
    assert_eq!(h.payload(&p), [1, 2, 3, 4, 5]);
    assert_eq!(h.write(&map, &[1, 2, 3, 4, 5]), p);
    // Without the map nothing is read but the payload is still found.
    let h = RtpHeader::parse(&p, &ExtensionMap::new()).unwrap();
    assert_eq!(h.ext, ExtensionValues::default());
    assert_eq!(h.payload(&p), [1, 2, 3, 4, 5]);
}

fn all_values() -> ExtensionValues {
    ExtensionValues {
        mid: Some("m".into()),
        rid: Some("r".into()),
        rrid: Some("rr".into()),
        abs_send_time: Some(0xab_cdef),
        transport_cc: Some(4242),
        audio_level: Some((false, 127)),
        video_orientation: Some(1),
        transmission_offset: Some(-3),
        playout_delay: Some((10, 4095)),
    }
}

fn all_map(base: u8) -> ExtensionMap {
    let mut m = ExtensionMap::new();
    for (i, e) in Extension::ALL.into_iter().enumerate() {
        m.insert(base + i as u8, e);
    }
    m
}

#[test]
fn rtp_round_trips() {
    let ext = all_values();
    for (map, two_byte) in [(all_map(1), false), (all_map(100), true)] {
        for padding_len in [0, 1, 7] {
            for csrc in [vec![], vec![9, 8, 7]] {
                let h = RtpHeader {
                    marker: true,
                    payload_type: 100,
                    sequence_number: 7,
                    timestamp: 8,
                    ssrc: 9,
                    csrc,
                    ext: ext.clone(),
                    header_len: 0,
                    padding_len,
                };
                let p = h.write(&map, b"payload!");
                let profile =
                    u16::from_be_bytes([p[12 + 4 * h.csrc.len()], p[13 + 4 * h.csrc.len()]]);
                assert_eq!(profile, if two_byte { 0x1000 } else { 0xbede });
                let g = RtpHeader::parse(&p, &map).unwrap();
                assert_eq!(g.payload(&p), b"payload!");
                assert_eq!(g.header_len % 4, 0);
                assert_eq!(RtpHeader { header_len: 0, ..g }, h);
            }
        }
    }
    // A long value forces the two-byte form even with small ids.
    let map = all_map(1);
    let h = RtpHeader {
        ext: ExtensionValues {
            mid: Some("x".repeat(17)),
            ..ExtensionValues::default()
        },
        ..RtpHeader::default()
    };
    let p = h.write(&map, &[]);
    assert_eq!(&p[12..14], &[0x10, 0x00]);
    assert_eq!(RtpHeader::parse(&p, &map).unwrap().ext.mid, h.ext.mid);
    // No extensions: no X bit, 12-byte header.
    let p = RtpHeader::default().write(&map, b"x");
    assert_eq!(p.len(), 13);
    assert_eq!(p[0], 0x80);
    // Values for unmapped extensions are left out.
    let p = RtpHeader {
        ext: all_values(),
        ..RtpHeader::default()
    }
    .write(&ExtensionMap::new(), b"");
    assert_eq!(p.len(), 12);
}

#[test]
fn rtp_parse_edge_cases() {
    let map = all_map(1);
    let base = |b0: u8| {
        let mut p = vec![b0, 0x60, 0, 1, 0, 0, 0, 2, 0, 0, 0, 3];
        p.extend_from_slice(b"pay");
        p
    };
    assert!(RtpHeader::parse(&base(0x80), &map).is_some());
    assert!(RtpHeader::parse(&base(0x40), &map).is_none()); // version 1
    assert!(RtpHeader::parse(&base(0x81), &map).is_none()); // CSRC runs past the end (3 bytes)
    assert!(RtpHeader::parse(&base(0x80)[..11], &map).is_none());
    // Padding count 0 and padding larger than the packet.
    let mut p = base(0xa0);
    *p.last_mut().unwrap() = 0;
    assert!(RtpHeader::parse(&p, &map).is_none());
    *p.last_mut().unwrap() = 4;
    assert!(RtpHeader::parse(&p, &map).is_none());
    *p.last_mut().unwrap() = 3;
    let h = RtpHeader::parse(&p, &map).unwrap();
    assert_eq!(h.payload(&p), b"");
    // Extension length past the end.
    let mut p = base(0x90);
    p.truncate(12);
    p.extend_from_slice(&[0xbe, 0xde, 0, 2, 0x10, 0x55, 0, 0]);
    assert!(RtpHeader::parse(&p, &map).is_none());
    // Padding bytes, an unknown id, a wrong-size value and id 15 (stop) inside the block.
    let mut p = base(0x90);
    p.truncate(12);
    p.extend_from_slice(&[0xbe, 0xde, 0, 3]);
    p.extend_from_slice(&[0, 0, 0xc0, 0x77, 0x50, 1, 0x70, 9, 0xf0, 0x60, 1, 0]);
    let h = RtpHeader::parse(&p, &map).unwrap();
    assert_eq!(h.ext.transport_cc, None); // id 5 (transport-cc) with 1 byte: ignored
    assert_eq!(h.ext.video_orientation, Some(9));
    assert_eq!(h.ext.audio_level, None); // after id 15: not read
    assert_eq!(h.header_len, 28);
    // Unknown extension profile: skipped entirely.
    let mut p = base(0x90);
    p.truncate(12);
    p.extend_from_slice(&[0x12, 0x34, 0, 1, 0x10, 0x55, 0, 0, 7]);
    let h = RtpHeader::parse(&p, &map).unwrap();
    assert_eq!(h.ext, ExtensionValues::default());
    assert_eq!(h.payload(&p), [7]);
    // Two-byte form with zero-length and padding entries.
    let mut p = base(0x90);
    p.truncate(12);
    p.extend_from_slice(&[0x10, 0x00, 0, 2, 0, 1, 0, 5, 2, 0x12, 0x34, 0]);
    let h = RtpHeader::parse(&p, &map).unwrap();
    assert_eq!(h.ext.transport_cc, Some(0x1234));
    assert_eq!(h.ext.mid, None);
}

#[test]
fn demux_and_helpers() {
    assert!(is_rtcp(&hex(PION_PLI)));
    assert!(!is_rtcp(&hex(PION_RTP_ONE_BYTE)));
    assert!(!is_rtcp(&[0x80, 200]));
    assert!(is_rtcp(&[0x80, 223, 0, 0]));
    assert!(!is_rtcp(&[0x80, 224, 0, 0]));
    assert!(!is_rtcp(&[0x80, 0xe0 - 0x21, 0, 0]));
    let t = std::time::UNIX_EPOCH + Duration::from_millis(1500);
    assert_eq!(ntp_time(t), (2_208_988_801u64 << 32) | (1 << 31));
    assert_eq!(compact_ntp(0x1122_3344_5566_7788), 0x3344_5566);
    assert_eq!(abs_send_time(Duration::from_millis(250)), 1 << 16);
    assert_eq!(abs_send_time(Duration::from_secs(64)), 0);
}

// --- RTCP ---

#[test]
fn pion_rtcp_vectors() {
    let cases: Vec<(&str, Rtcp)> = vec![
        (
            PION_SR,
            Rtcp::SenderReport {
                ssrc: 0x0102_0304,
                info: SenderInfo {
                    ntp_time: 0xe123_4567_89ab_cdef,
                    rtp_time: 0x1111_1111,
                    packet_count: 100,
                    octet_count: 12345,
                },
                reports: vec![ReportBlock {
                    ssrc: 0xaabb_ccdd,
                    fraction_lost: 25,
                    cumulative_lost: 1000,
                    extended_highest_seq: 0x0001_5000,
                    jitter: 33,
                    last_sr: 0x4567_8912,
                    delay_since_last_sr: 0x0001_0000,
                }],
            },
        ),
        (
            PION_RR,
            Rtcp::ReceiverReport {
                ssrc: 0x0506_0708,
                reports: vec![
                    ReportBlock {
                        ssrc: 1,
                        extended_highest_seq: 7,
                        ..ReportBlock::default()
                    },
                    ReportBlock {
                        ssrc: 2,
                        fraction_lost: 255,
                        cumulative_lost: 0x7f_ffff,
                        extended_highest_seq: 0xffff_ffff,
                        jitter: 9,
                        last_sr: 1,
                        delay_since_last_sr: 2,
                    },
                ],
            },
        ),
        (
            PION_NACK,
            Rtcp::Nack {
                sender_ssrc: 1,
                media_ssrc: 2,
                lost: vec![100, 101, 105, 116, 117, 140, 65535, 3],
            },
        ),
        (
            PION_PLI,
            Rtcp::Pli {
                sender_ssrc: 3,
                media_ssrc: 4,
            },
        ),
        (
            PION_FIR,
            Rtcp::Fir {
                sender_ssrc: 5,
                entries: vec![(6, 7), (8, 255)],
            },
        ),
        (
            PION_REMB,
            Rtcp::Remb {
                sender_ssrc: 9,
                bitrate: 1_234_560, // 1234567 with an 18-bit mantissa
                ssrcs: vec![10, 11],
            },
        ),
        (
            PION_SDES,
            Rtcp::SourceDescription(vec![(0x1234_5678, vec![(1, "user@example".into())])]),
        ),
        (
            PION_BYE,
            Rtcp::Goodbye {
                ssrcs: vec![1, 2],
                reason: Some("bye now".into()),
            },
        ),
    ];
    let mut compound = Vec::new();
    for (bytes, want) in &cases {
        let b = hex(bytes);
        assert_eq!(
            parse_compound(&b).unwrap(),
            std::slice::from_ref(want),
            "{bytes}"
        );
        assert_eq!(write_compound(std::slice::from_ref(want)), b, "{want:?}");
        compound.extend_from_slice(&b);
    }
    let all: Vec<Rtcp> = cases.into_iter().map(|(_, p)| p).collect();
    assert_eq!(parse_compound(&compound).unwrap(), all);
    assert_eq!(write_compound(&all), compound);
}

/// Reconstructs arrival times (µs) from feedback.
fn arrivals_of(fb: &TwccFeedback) -> Vec<(u16, i64)> {
    let mut t = i64::from(fb.reference_time) * 64_000;
    fb.packets
        .iter()
        .filter_map(|&(s, d)| {
            d.map(|d| {
                t += d * 250;
                (s, t)
            })
        })
        .collect()
}

#[test]
fn pion_twcc_recorder_vectors() {
    for (bytes, arrivals) in [
        (PION_TWCC_1, &TWCC_ARRIVALS[..29]),
        (PION_TWCC_2, &TWCC_ARRIVALS[29..]),
    ] {
        let b = hex(bytes);
        let p = parse_compound(&b).unwrap();
        let [Rtcp::TransportCc(fb)] = &p[..] else {
            panic!("{p:?}")
        };
        assert_eq!((fb.sender_ssrc, fb.media_ssrc), (0xabcd_ef01, 0x1357));
        let mut want: Vec<(u16, i64)> = arrivals.to_vec();
        want.sort_by_key(|&(s, _)| s.wrapping_sub(65530));
        assert_eq!(arrivals_of(fb), want);
        assert_eq!(write_compound(&p), b);
    }
    // The first feedback: base 65530, 64 statuses (27..=56 lost).
    let p = parse_compound(&hex(PION_TWCC_1)).unwrap();
    let Rtcp::TransportCc(fb) = &p[0] else {
        panic!()
    };
    assert_eq!((fb.base_seq, fb.packets.len(), fb.fb_count), (65530, 64, 0));
    assert_eq!(fb.packets[33], (27, None));
    assert_eq!(fb.packets[63].0, 57);
}

#[test]
fn twcc_receiver_matches_pion() {
    let t0 = Instant::now();
    let mut rx = TwccReceiver::new();
    for &(seq, us) in &TWCC_ARRIVALS[..29] {
        rx.on_received(seq, t0 + Duration::from_micros(us as u64));
    }
    let at = t0 + Duration::from_millis(131);
    let fb = rx.poll_feedback(at, 0xabcd_ef01, 0x1357).unwrap();
    assert_eq!(write_compound(&[fb]), hex(PION_TWCC_1));
    assert!(rx.poll_feedback(at, 0xabcd_ef01, 0x1357).is_none());
    for &(seq, us) in &TWCC_ARRIVALS[29..] {
        rx.on_received(seq, t0 + Duration::from_micros(us as u64));
    }
    // Not due yet (2 packets, < 100 ms since the last feedback).
    assert!(
        rx.poll_feedback(at + Duration::from_millis(80), 1, 2)
            .is_none()
    );
    let fb = rx
        .poll_feedback(at + Duration::from_millis(100), 0xabcd_ef01, 0x1357)
        .unwrap();
    assert_eq!(write_compound(&[fb]), hex(PION_TWCC_2));
}

#[test]
fn rtcp_round_trips() {
    let all = rtcp_samples();
    let bytes = write_compound(&all);
    assert_eq!(bytes.len() % 4, 0);
    assert_eq!(parse_compound(&bytes).unwrap(), all);
    for p in &all {
        let b = write_compound(std::slice::from_ref(p));
        assert_eq!(
            parse_compound(&b).unwrap(),
            std::slice::from_ref(p),
            "{p:?}"
        );
    }
}

#[test]
fn twcc_chunk_kinds() {
    let mk = |deltas: Vec<Option<i64>>| TwccFeedback {
        sender_ssrc: 1,
        media_ssrc: 2,
        base_seq: 100,
        reference_time: 5,
        fb_count: 1,
        packets: deltas
            .into_iter()
            .enumerate()
            .map(|(i, d)| (100 + i as u16, d))
            .collect(),
    };
    // (deltas, expected first chunk)
    let cases: Vec<(Vec<Option<i64>>, u16)> = vec![
        // Run of 20 small: run-length chunk, symbol 1.
        (vec![Some(4); 20], 0x2000 | 20),
        // Run of 9000 lost (more than one run-length chunk) then one received.
        (
            std::iter::repeat_n(None, 9000).chain([Some(1)]).collect(),
            0x1fff,
        ),
        // Mixed small / lost: one-bit vector of 14.
        (
            (0..14).map(|i| (i % 2 == 0).then_some(1)).collect(),
            0x8000 | 0b10_1010_1010_1010,
        ),
        // With a large delta: two-bit vectors of 7.
        (
            vec![
                Some(1),
                None,
                Some(300),
                Some(-2),
                Some(0),
                None,
                Some(255),
                Some(3),
            ],
            0xc000 | (1 << 12) | (2 << 8) | (2 << 6) | (1 << 4) | 1,
        ),
        // Run of large deltas.
        (vec![Some(1000); 8], 0x4000 | 8),
    ];
    for (deltas, first_chunk) in cases {
        let fb = mk(deltas);
        let b = write_compound(&[Rtcp::TransportCc(fb.clone())]);
        assert_eq!(u16::from_be_bytes([b[20], b[21]]), first_chunk, "{fb:?}");
        assert_eq!(parse_compound(&b).unwrap(), [Rtcp::TransportCc(fb)]);
    }
    // Out-of-range deltas are clamped.
    let b = write_compound(&[Rtcp::TransportCc(mk(vec![Some(100_000), Some(-100_000)]))]);
    let Rtcp::TransportCc(fb) = &parse_compound(&b).unwrap()[0] else {
        panic!()
    };
    assert_eq!(fb.packets[0].1, Some(32767));
    assert_eq!(fb.packets[1].1, Some(-32768));
    // Too many statuses: kept as Unknown.
    let mut big = hex("8fcd0004 00000001 00000002 0000 ffff 000000 00 1fff 0000");
    big[2..4].copy_from_slice(&5u16.to_be_bytes());
    let p = parse_compound(&big).unwrap();
    assert!(
        matches!(
            p[0],
            Rtcp::Unknown {
                packet_type: 205,
                fmt: 15,
                ..
            }
        ),
        "{p:?}"
    );
}

#[test]
fn rtcp_errors_and_tolerance() {
    assert_eq!(parse_compound(&[]).unwrap(), []);
    assert_eq!(parse_compound(&[0x80, 200, 0]), Err(Error::TooShort));
    assert_eq!(parse_compound(&[0x40, 200, 0, 0]), Err(Error::BadVersion));
    assert_eq!(
        parse_compound(&[0x80, 201, 0, 1, 0, 0]),
        Err(Error::TooShort)
    );
    // RR claiming one report block with only the SSRC.
    assert!(matches!(
        parse_compound(&[0x81, 201, 0, 1, 0, 0, 0, 1]),
        Err(Error::Malformed(_))
    ));
    // Bad padding.
    assert_eq!(
        parse_compound(&[0xa0, 201, 0, 1, 0, 0, 0, 0]),
        Err(Error::BadPadding)
    );
    assert_eq!(
        parse_compound(&[0xa0, 201, 0, 1, 0, 0, 0, 9]),
        Err(Error::BadPadding)
    );
    // A valid packet followed by garbage fails as a whole.
    let mut b = hex(PION_PLI);
    b.push(0x80);
    assert!(parse_compound(&b).is_err());
    // Unknown type and unknown feedback format are kept.
    let p = parse_compound(&hex("80cc0001 01020304 81cd0002 00000001 00000002")).unwrap();
    assert_eq!(
        p,
        [
            Rtcp::Unknown {
                packet_type: 204,
                fmt: 0,
                data: vec![1, 2, 3, 4]
            },
            Rtcp::Unknown {
                packet_type: 205,
                fmt: 1, // NACK without FCI is still a NACK
                data: vec![]
            }
        ]
        .into_iter()
        .map(|p| match p {
            Rtcp::Unknown {
                packet_type: 205, ..
            } => Rtcp::Nack {
                sender_ssrc: 1,
                media_ssrc: 2,
                lost: vec![],
            },
            p => p,
        })
        .collect::<Vec<_>>()
    );
    // Non-REMB application feedback is Unknown; SR with a profile extension is tolerated.
    let p = parse_compound(&hex("8fce0003 00000001 00000000 41424344")).unwrap();
    assert!(matches!(
        p[0],
        Rtcp::Unknown {
            packet_type: 206,
            fmt: 15,
            ..
        }
    ));
    let mut sr = hex(PION_SR);
    sr[3] += 1;
    sr.extend_from_slice(&[9, 9, 9, 9]);
    assert_eq!(
        parse_compound(&sr).unwrap(),
        parse_compound(&hex(PION_SR)).unwrap()
    );
    // Truncated variants of every sample never panic.
    let all = write_compound(&rtcp_samples());
    for n in 0..all.len() {
        let _ = parse_compound(&all[..n]);
    }
    assert!(Error::Malformed("x").to_string().contains('x'));
}

#[test]
fn nack_pairs_preserve_order() {
    let lost = [1u16, 2, 17, 18, 18, 3, 65535, 15];
    let b = write_compound(&[Rtcp::Nack {
        sender_ssrc: 0,
        media_ssrc: 0,
        lost: lost.to_vec(),
    }]);
    let p = parse_compound(&b).unwrap();
    assert_eq!(
        p,
        [Rtcp::Nack {
            sender_ssrc: 0,
            media_ssrc: 0,
            lost: lost.to_vec()
        }]
    );
}

// --- streams ---

fn ms(n: u64) -> Duration {
    Duration::from_millis(n)
}

#[test]
fn send_stream_rtx_and_history() {
    let map = video_map();
    let t0 = Instant::now();
    let mut s = SendStream::new(0x1111, 90_000, Some(0x2222), 65534);
    let ext = ExtensionValues {
        mid: Some("v".into()),
        transport_cc: Some(1),
        ..ExtensionValues::default()
    };
    let p: Vec<_> = (0..4u8)
        .map(|i| s.write(t0, 96, i == 3, 1000 + u32::from(i), &[i; 10], &ext, &map))
        .collect();
    let seqs: Vec<u16> = p
        .iter()
        .map(|x| RtpHeader::parse(x, &map).unwrap().sequence_number)
        .collect();
    assert_eq!(seqs, [65534, 65535, 0, 1]);
    assert_eq!(
        (s.packets_sent(), s.octets_sent(), s.next_seq()),
        (4, 40, 2)
    );
    // RTX.
    let r = s.resend(t0 + ms(5), &[0, 1, 7], Some(97), &map);
    assert_eq!(r.len(), 2);
    let h = RtpHeader::parse(&r[1], &map).unwrap();
    assert_eq!(
        (h.ssrc, h.payload_type, h.marker, h.timestamp),
        (0x2222, 97, true, 1003)
    );
    assert_eq!(h.sequence_number, (65534u16 ^ 0x8000).wrapping_add(1));
    assert_eq!(h.ext, ext);
    assert_eq!(h.payload(&r[1]), [&[0, 1][..], &[3; 10]].concat());
    // At most once per 10 ms.
    assert!(s.resend(t0 + ms(10), &[0], Some(97), &map).is_empty());
    assert_eq!(s.resend(t0 + ms(16), &[0], Some(97), &map).len(), 1);
    // Without RTX: the original packet; with resend_with the extensions can change.
    let r = s.resend_with(t0 + ms(30), &[65535], None, &map, |e| {
        e.transport_cc = Some(99);
    });
    let h = RtpHeader::parse(&r[0], &map).unwrap();
    assert_eq!(
        (h.ssrc, h.sequence_number, h.ext.transport_cc),
        (0x1111, 65535, Some(99))
    );
    assert_eq!(h.payload(&r[0]), [1; 10]);
    assert_eq!(s.packets_resent(), 4);
    // History ages out after 2 s.
    assert!(s.resend(t0 + ms(2100), &[65535], None, &map).is_empty());
    // And is bounded by count.
    let mut s = SendStream::new(1, 48_000, None, 0);
    for i in 0..3000u32 {
        s.write(t0, 111, false, i, b"a", &ExtensionValues::default(), &map);
    }
    assert!(s.resend(t0, &[100], None, &map).is_empty());
    assert_eq!(s.resend(t0, &[2999], None, &map).len(), 1);
}

#[test]
fn sender_report_and_rtt() {
    let map = audio_map();
    let t0 = Instant::now();
    let mut s = SendStream::new(5, 48_000, None, 0);
    assert!(s.sender_report(t0, 1).is_none());
    s.write(
        t0,
        111,
        false,
        48_000,
        b"abc",
        &ExtensionValues::default(),
        &map,
    );
    let info = s
        .sender_report(t0 + ms(500), 0x1234_5678_0000_0000)
        .unwrap();
    assert_eq!(info.rtp_time, 48_000 + 24_000);
    assert_eq!((info.packet_count, info.octet_count), (1, 3));
    assert_eq!(info.ntp_time, 0x1234_5678_0000_0000);

    // Remote receives the SR at ntp T, reports 10 ms later; we get the report at T + 60 ms.
    let sr_ntp: u64 = 0x0000_1000_8000_0000;
    let mut rx = RecvStream::new(5, 48_000, false);
    rx.receive(t0, 0, 48_000);
    rx.handle_sender_report(
        t0,
        &SenderInfo {
            ntp_time: sr_ntp,
            ..info
        },
    );
    let rb = rx.report_block(t0 + ms(10)).unwrap();
    assert_eq!(rb.last_sr, compact_ntp(sr_ntp));
    assert_eq!(rb.delay_since_last_sr, 655); // 10 ms in 1/65536 s
    let now_ntp = sr_ntp + ((60u64 << 32) / 1000);
    s.handle_report_block(t0, now_ntp, &rb);
    let rtt = s.rtt().unwrap();
    assert!(rtt > ms(49) && rtt < ms(51), "{rtt:?}");
    assert_eq!(s.remote_report().unwrap().ssrc, 5);
    // No LSR: no RTT update.
    let mut s2 = SendStream::new(5, 48_000, None, 0);
    s2.handle_report_block(t0, now_ntp, &ReportBlock::default());
    assert_eq!(s2.rtt(), None);
}

#[test]
fn recv_stream_rollover_and_reorder() {
    let t0 = Instant::now();
    let mut r = RecvStream::new(1, 90_000, false);
    assert_eq!(r.receive(t0, 65533, 0), Some(65533));
    assert_eq!(r.receive(t0, 65535, 0), Some(65535));
    assert_eq!(r.receive(t0, 1, 0), Some(65537));
    assert_eq!(r.receive(t0, 65534, 0), Some(65534)); // late, before the wrap
    assert_eq!(r.receive(t0, 0, 0), Some(65536)); // late, after the wrap
    assert_eq!(r.receive(t0, 0, 0), None); // duplicate
    assert_eq!(r.receive(t0, 2, 0), Some(65538));
    assert_eq!(r.extended_highest_seq(), Some(65538));
    let rb = r.report_block(t0).unwrap();
    assert_eq!(rb.extended_highest_seq, 0x0001_0002);
    assert_eq!((rb.cumulative_lost, rb.fraction_lost), (0, 0));
    // Far too old.
    for s in 3..3000u16 {
        r.receive(t0, s, 0);
    }
    assert_eq!(r.receive(t0, 10, 0), None);
    // Before the first cycle.
    let mut r = RecvStream::new(1, 90_000, false);
    r.receive(t0, 5, 0);
    assert_eq!(r.receive(t0, 65530, 0), None);
    assert_eq!(r.receive(t0, 3, 0), Some(3));
}

#[test]
fn recv_stream_loss_statistics() {
    let t0 = Instant::now();
    let mut r = RecvStream::new(1, 90_000, false);
    assert!(r.report_block(t0).is_none());
    // 100 packets, every 4th lost.
    for s in 0..100u16 {
        if s % 4 != 1 {
            r.receive(t0, s, 0);
        }
    }
    let rb = r.report_block(t0).unwrap();
    assert_eq!(rb.cumulative_lost, 25);
    assert_eq!(rb.fraction_lost, 64); // 25 % of 256
    // Next interval: no loss.
    for s in 100..200u16 {
        r.receive(t0, s, 0);
    }
    let rb = r.report_block(t0).unwrap();
    assert_eq!((rb.cumulative_lost, rb.fraction_lost), (25, 0));
    // Late arrivals of lost packets reduce the cumulative count.
    r.receive(t0, 1, 0);
    r.receive(t0, 5, 0);
    assert_eq!(r.report_block(t0).unwrap().cumulative_lost, 23);
    assert_eq!(r.packets_received(), 177);
}

#[test]
fn jitter_rfc3550() {
    let t0 = Instant::now();
    // Constant spacing: no jitter.
    let mut r = RecvStream::new(1, 90_000, false);
    for i in 0..50u32 {
        r.receive(t0 + ms(u64::from(i) * 20), i as u16, i * 1800);
    }
    assert_eq!(r.jitter(), 0);
    // Alternating +-5 ms arrival offsets (450 ticks): J converges to |D| = 900.
    let mut r = RecvStream::new(1, 90_000, false);
    for i in 0..400u32 {
        let off = if i % 2 == 0 { 0 } else { 10 };
        r.receive(t0 + ms(u64::from(i) * 20 + off), i as u16, i * 1800);
    }
    assert!((880..=900).contains(&r.jitter()), "{}", r.jitter());
    assert_eq!(r.report_block(t0).unwrap().jitter, r.jitter());
}

#[test]
fn nack_generation() {
    let t0 = Instant::now();
    let mut r = RecvStream::new(1, 90_000, true);
    assert_eq!(r.poll_timeout(), None);
    for s in [10u16, 11, 14, 15] {
        r.receive(t0, s, 0);
    }
    assert_eq!(r.missing_count(), 2);
    // Reordering wait: 20 ms with the default RTT.
    assert_eq!(r.poll_nack(t0 + ms(5)), None);
    assert_eq!(r.poll_timeout(), Some(t0 + ms(20)));
    assert_eq!(r.poll_nack(t0 + ms(20)), Some(vec![12, 13]));
    assert_eq!(r.poll_nack(t0 + ms(50)), None);
    // 12 is recovered (RTX): only 13 is NACKed again after one RTT.
    r.receive(t0 + ms(60), 12, 0);
    assert_eq!(r.poll_nack(t0 + ms(120)), Some(vec![13]));
    // With a 30 ms RTT, re-NACKs every 30 ms, and give-up after 10 tries.
    r.set_rtt(ms(30));
    let mut tries = 2;
    let mut t = t0 + ms(120);
    while let Some(v) = {
        t += ms(30);
        r.poll_nack(t)
    } {
        assert_eq!(v, [13]);
        tries += 1;
    }
    assert_eq!(tries, 10);
    assert_eq!(r.missing_count(), 0);
    // Give-up after 1 s even with few tries.
    let mut r = RecvStream::new(1, 90_000, true);
    r.receive(t0, 0, 0);
    r.receive(t0, 2, 0);
    r.set_rtt(ms(600));
    assert_eq!(r.poll_nack(t0 + ms(30)), Some(vec![1]));
    assert_eq!(r.poll_nack(t0 + ms(700)), Some(vec![1]));
    assert_eq!(r.poll_nack(t0 + ms(1400)), None);
    assert_eq!(r.missing_count(), 0);
    // A huge jump is a discontinuity, not 5000 losses; across the wrap gaps are found.
    let mut r = RecvStream::new(1, 90_000, true);
    r.receive(t0, 100, 0);
    r.receive(t0, 6000, 0);
    assert_eq!(r.missing_count(), 0);
    let mut r = RecvStream::new(1, 90_000, true);
    r.receive(t0, 65534, 0);
    r.receive(t0, 1, 0);
    assert_eq!(r.poll_nack(t0 + ms(25)), Some(vec![65535, 0]));
    // Disabled.
    let mut r = RecvStream::new(1, 90_000, false);
    r.receive(t0, 1, 0);
    r.receive(t0, 3, 0);
    assert_eq!(r.poll_nack(t0 + ms(100)), None);
    assert_eq!(r.poll_timeout(), None);
}

#[test]
fn nack_under_simulated_loss() {
    // 1000 packets, 10 % deterministic pseudo-random loss; NACKs go back over a 40 ms RTT link
    // and retransmissions are lost 10 % of the time as well. Everything is recovered.
    let map = video_map();
    let t0 = Instant::now();
    let mut tx = SendStream::new(1, 90_000, Some(2), 40_000);
    let mut rx = RecvStream::new(1, 90_000, true);
    rx.set_rtt(ms(40));
    let mut rng = 0x1234_5678u32;
    let mut lossy = move || {
        rng ^= rng << 13;
        rng ^= rng >> 17;
        rng ^= rng << 5;
        rng % 10 == 0
    };
    let mut in_flight: Vec<(Instant, Vec<u8>)> = Vec::new();
    let mut got = std::collections::BTreeSet::new();
    let mut nacked = 0;
    for step in 0..3000u64 {
        let now = t0 + ms(step);
        if step < 1000 {
            let p = tx.write(
                now,
                96,
                false,
                step as u32 * 90,
                &[1; 100],
                &ExtensionValues::default(),
                &map,
            );
            if !lossy() {
                in_flight.push((now + ms(20), p));
            }
        }
        let (due, rest): (Vec<_>, Vec<_>) = in_flight.into_iter().partition(|(t, _)| *t <= now);
        in_flight = rest;
        for (_, p) in due {
            let h = RtpHeader::parse(&p, &map).unwrap();
            let (seq, ts) = if h.ssrc == 2 {
                let pl = h.payload(&p);
                (u16::from_be_bytes([pl[0], pl[1]]), h.timestamp)
            } else {
                (h.sequence_number, h.timestamp)
            };
            if let Some(e) = rx.receive(now, seq, ts) {
                got.insert(e);
            }
        }
        if let Some(lost) = rx.poll_nack(now) {
            nacked += lost.len();
            // NACK reaches the sender after 20 ms; model as immediate resend arriving 40 ms later.
            for p in tx.resend(now, &lost, Some(97), &map) {
                if !lossy() {
                    in_flight.push((now + ms(40), p));
                }
            }
        }
    }
    assert_eq!(got.len(), 1000);
    assert!((90..200).contains(&nacked), "{nacked}");
    assert_eq!(rx.missing_count(), 0);
}

// --- TWCC + estimator ---

#[test]
fn twcc_end_to_end() {
    let t0 = Instant::now();
    let mut tx = TwccSender::new();
    let mut rx = TwccReceiver::new();
    let mut results = Vec::new();
    for i in 0..70_000u64 {
        let seq = tx.next_seq();
        let now = t0 + Duration::from_micros(i * 1000);
        tx.on_sent(seq, now, 1000);
        if i % 50 != 7 {
            rx.on_received(seq, now + ms(30));
        }
        if let Some(Rtcp::TransportCc(fb)) = rx.poll_feedback(now + ms(30), 1, 2) {
            let b = write_compound(&[Rtcp::TransportCc(fb)]);
            let [Rtcp::TransportCc(fb)] = &parse_compound(&b).unwrap()[..] else {
                panic!()
            };
            results.extend(tx.on_feedback(now + ms(50), fb));
        }
    }
    // Everything except the tail is reported once (lost packets possibly twice if reordered;
    // here never).
    let received = results.iter().filter(|r| r.received.is_some()).count();
    let lost = results.iter().filter(|r| r.received.is_none()).count();
    assert!(received > 68_000, "{received}");
    // All lost packets except possibly the last unreported feedback's.
    let all_lost = (0..70_000u64).filter(|i| i % 50 == 7).count();
    assert!(lost <= all_lost && lost + 3 >= all_lost, "{lost}");
    // Arrival spacing matches send spacing (1 ms) for consecutive received packets.
    for w in results.windows(2) {
        if let (Some(a), Some(b)) = (w[0].received, w[1].received) {
            if w[1].seq == w[0].seq + 1 {
                let d = b.saturating_duration_since(a);
                assert!(
                    d >= Duration::from_micros(750) && d <= Duration::from_micros(1250),
                    "{d:?}"
                );
            }
        }
    }
    assert!(results.windows(2).all(|w| w[0].seq < w[1].seq));
}

/// A simulated bottleneck link: FIFO queue drained at `capacity` bps, 20 ms propagation,
/// optional random loss; the sender paces at the estimate; feedback every 100 ms.
fn simulate(
    capacity_bps: f64,
    loss_pct: u32,
    initial: u64,
    secs: u64,
) -> (u64, BandwidthEstimator) {
    let t0 = Instant::now();
    let mut bwe = BandwidthEstimator::new(initial);
    let mut tx = TwccSender::new();
    let mut rx = TwccReceiver::new();
    let mut link_free = t0;
    let mut arrivals: Vec<(Instant, u16)> = Vec::new();
    let mut rng = 0x9e37_79b9u32;
    let mut credit = 0.0f64;
    let size = 1200usize;
    for step in 0..(secs * 1000) {
        let now = t0 + ms(step);
        credit += bwe.estimate() as f64 / 1000.0;
        while credit >= (size * 8) as f64 {
            credit -= (size * 8) as f64;
            let seq = tx.next_seq();
            tx.on_sent(seq, now, size);
            rng ^= rng << 13;
            rng ^= rng >> 17;
            rng ^= rng << 5;
            if rng % 100 < loss_pct {
                continue;
            }
            let start = link_free.max(now);
            let tx_time = Duration::from_secs_f64((size * 8) as f64 / capacity_bps);
            link_free = start + tx_time;
            // Drop-tail at 500 ms of queue.
            if link_free.saturating_duration_since(now) > ms(500) {
                link_free = start;
                continue;
            }
            arrivals.push((link_free + ms(20), seq));
        }
        let (due, rest): (Vec<_>, Vec<_>) = arrivals.into_iter().partition(|(t, _)| *t <= now);
        arrivals = rest;
        for (t, seq) in due {
            rx.on_received(seq, t);
        }
        while let Some(Rtcp::TransportCc(fb)) = rx.poll_feedback(now, 1, 2) {
            let res = tx.on_feedback(now + ms(20), &fb);
            bwe.on_packet_results(now + ms(20), &res);
        }
    }
    (bwe.estimate(), bwe)
}

#[test]
fn estimator_grows_on_clean_link() {
    let (e, bwe) = simulate(50_000_000.0, 0, 300_000, 20);
    assert!(e > 1_000_000, "{e}");
    assert_eq!(bwe.usage(), BandwidthUsage::Normal);
    assert!(bwe.acknowledged_bitrate().unwrap() > 500_000);
}

#[test]
fn estimator_backs_off_at_bottleneck() {
    let (e, _) = simulate(1_000_000.0, 0, 3_000_000, 20);
    assert!(e < 1_300_000, "{e}");
    assert!(e > 300_000, "{e}");
}

#[test]
fn estimator_backs_off_under_loss() {
    let (e, _) = simulate(50_000_000.0, 25, 2_000_000, 10);
    assert!(e < 1_000_000, "{e}");
    let (e, _) = simulate(50_000_000.0, 1, 1_000_000, 10);
    assert!(e > 1_000_000, "{e}");
}

#[test]
fn estimator_bounds_and_remb() {
    let mut b = BandwidthEstimator::new(10).with_bounds(50_000, 100_000);
    assert_eq!(b.estimate(), 50_000);
    b = BandwidthEstimator::new(1_000_000).with_bounds(50_000, 100_000);
    assert_eq!(b.estimate(), 100_000);
    let mut b = BandwidthEstimator::new(1_000_000);
    b.set_remote_estimate(400_000);
    assert_eq!(b.estimate(), 400_000);
    b.set_remote_estimate(0);
    assert_eq!(b.estimate(), 1_000_000);
    b.on_packet_results(Instant::now(), &[]);
    assert_eq!(b.acknowledged_bitrate(), None);
}
